#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int N = 50005;
const int NEG_INF = -1e9;

int n, m;
int A[N];
vector<int> adj[N];

int fa[N], dep[N], siz[N], son[N];
int top_node[N], dfn[N], rnk[N], tot;

void dfs1(int u, int p, int d) {
    fa[u] = p; dep[u] = d; siz[u] = 1; son[u] = 0;
    int max_siz = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u, d + 1);
        siz[u] += siz[v];
        if (siz[v] > max_siz) { max_siz = siz[v]; son[u] = v; }
    }
}

void dfs2(int u, int t) {
    top_node[u] = t; dfn[u] = ++tot; rnk[tot] = u;
    if (son[u]) dfs2(son[u], t);
    for (int v : adj[u]) {
        if (v == fa[u] || v == son[u]) continue;
        dfs2(v, v);
    }
}

// 0: 不选, 1: 选且为段端点, 2: 选且在段内部
struct State {
    int sum;
    int xor_val;
};

struct Node {
    State dp[6][3][3]; // dp[j][l][r]
    
    void init(int val) {
        for (int j = 0; j < 6; ++j)
            for (int l = 0; l < 3; ++l)
                for (int r = 0; r < 3; ++r)
                    dp[j][l][r].sum = NEG_INF;
        
        dp[0][0][0] = {0, 0};
        dp[1][1][1] = {val, val};
    }
    
    void reverse() {
        for (int j = 0; j < 6; ++j)
            for (int l = 0; l < 3; ++l)
                for (int r = l + 1; r < 3; ++r)
                    swap(dp[j][l][r], dp[j][r][l]);
    }
};

Node tree[N << 2];

Node merge(const Node& L, const Node& R) {
    Node res;
    for (int j = 0; j < 6; ++j)
        for (int l = 0; l < 3; ++l)
            for (int r = 0; r < 3; ++r)
                res.dp[j][l][r].sum = NEG_INF;
                
    for (int jl = 0; jl < 6; ++jl) {
        for (int ll = 0; ll < 3; ++ll) {
            for (int rl = 0; rl < 3; ++rl) {
                if (L.dp[jl][ll][rl].sum == NEG_INF) continue;
                int sum_l = L.dp[jl][ll][rl].sum;
                int xl = L.dp[jl][ll][rl].xor_val;
                
                for (int jr = 0; jr < 6; ++jr) {
                    if (jl + jr > 5) continue;
                    for (int lr = 0; lr < 3; ++lr) {
                        for (int rr = 0; rr < 3; ++rr) {
                            if (R.dp[jr][lr][rr].sum == NEG_INF) continue;
                            int sum_r = R.dp[jr][lr][rr].sum;
                            int xr = R.dp[jr][lr][rr].xor_val;
                            
                            int new_j, new_sum, new_xor;
                            
                            if (rl > 0 && lr > 0) {
                                if (rl == 2 && lr == 2) continue;
                                if (jl + jr - 1 > 5) continue;
                                new_j = jl + jr - 1;
                                new_xor = xl ^ xr;
                                
                                if (rl == 1 && lr == 1) new_sum = sum_l + sum_r - xl - xr + new_xor;
                                else if (rl == 1) new_sum = sum_l + sum_r - xl + new_xor;
                                else if (lr == 1) new_sum = sum_l + sum_r - xr + new_xor;
                                else new_sum = sum_l + sum_r + new_xor;
                            } else {
                                new_j = jl + jr;
                                if (new_j > 5) continue;
                                new_sum = sum_l + sum_r;
                                if (rl > 0) new_xor = xl;
                                else if (lr > 0) new_xor = xr;
                                else new_xor = 0;
                            }
                            
                            if (new_sum > res.dp[new_j][ll][rr].sum) {
                                res.dp[new_j][ll][rr].sum = new_sum;
                                res.dp[new_j][ll][rr].xor_val = new_xor;
                            }
                        }
                    }
                }
            }
        }
    }
    return res;
}

void build(int rt, int l, int r) {
    if (l == r) { tree[rt].init(A[rnk[l]]); return; }
    int mid = (l + r) >> 1;
    build(rt << 1, l, mid); build(rt << 1 | 1, mid + 1, r);
    tree[rt] = merge(tree[rt << 1], tree[rt << 1 | 1]);
}

void update(int rt, int l, int r, int pos, int val) {
    if (l == r) { tree[rt].init(val); return; }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(rt << 1, l, mid, pos, val);
    else update(rt << 1 | 1, mid + 1, r, pos, val);
    tree[rt] = merge(tree[rt << 1], tree[rt << 1 | 1]);
}

Node query(int rt, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return tree[rt];
    int mid = (l + r) >> 1;
    if (qr <= mid) return query(rt << 1, l, mid, ql, qr);
    if (ql > mid) return query(rt << 1 | 1, mid + 1, r, ql, qr);
    return merge(query(rt << 1, l, mid, ql, qr), query(rt << 1 | 1, mid + 1, r, ql, qr));
}

int query_path(int u, int v, int k) {
    vector<Node> segments;
    
    while (top_node[u] != top_node[v]) {
        if (dep[top_node[u]] > dep[top_node[v]]) {
            Node cur = query(1, 1, n, dfn[top_node[u]], dfn[u]);
            cur.reverse(); // 提取从上到下的链，反转成从u向上
            segments.push_back(cur);
            u = fa[top_node[u]];
        } else {
            Node cur = query(1, 1, n, dfn[top_node[v]], dfn[v]);
            // 本来是从上到下，我们留待最后统一反转一次
            segments.push_back(cur);
            v = fa[top_node[v]];
        }
    }
    
    if (dep[u] < dep[v]) {
        Node mid_res = query(1, 1, n, dfn[u], dfn[v]);
        segments.push_back(mid_res);
    } else {
        Node mid_res = query(1, 1, n, dfn[v], dfn[u]);
        mid_res.reverse();
        segments.push_back(mid_res);
    }
    
    // 将所有段逆序，因为刚才从两端向中间提取时是倒序的
    reverse(segments.begin(), segments.end());
    
    // 顺次合并，完美规避左覆盖右的端点歧义
    Node final_res = segments[0];
    for (size_t i = 1; i < segments.size(); ++i) {
        final_res = merge(final_res, segments[i]);
    }
    
    // 严格封闭路径的两端点
    for (int j = 0; j < 6; ++j) {
        for (int r = 1; r < 3; ++r) final_res.dp[j][1][r].sum = NEG_INF;
        for (int r = 1; r < 3; ++r) final_res.dp[j][2][r].sum = NEG_INF;
        for (int l = 1; l < 3; ++l) final_res.dp[j][l][1].sum = NEG_INF;
        for (int l = 1; l < 3; ++l) final_res.dp[j][l][2].sum = NEG_INF;
    }
    
    int ans = NEG_INF;
    for (int j = 1; j <= k; ++j) {
        ans = max(ans, final_res.dp[j][0][0].sum);
    }
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    if (!(cin >> n >> m)) return 0;
    for (int i = 1; i <= n; ++i) cin >> A[i];
    for (int i = 1; i < n; ++i) {
        int u, v; cin >> u >> v;
        adj[u].push_back(v); adj[v].push_back(u);
    }
    
    dfs1(1, 0, 1); dfs2(1, 1); build(1, 1, n);
    
    while (m--) {
        int op; cin >> op;
        if (op == 1) {
            int u, x; cin >> u >> x;
            update(1, 1, n, dfn[u], x);
        } else if (op == 2) {
            int u, v, k; cin >> u >> v >> k;
            cout << query_path(u, v, k) + 3 << "\n";
        }
    }
    return 0;
}
